ST.xhtml:p:
R_Trigger0(CLK := g_biFlatAbsOpen);
R_Trigger1(CLK := g_biFlatAbsClose);

IF R_Trigger0.Q THEN
  g_boFlatAbsDone := FALSE;
  nSwitchState := 1;
END_IF;

IF R_Trigger1.Q THEN
  g_boFlatAbsDone := FALSE;
  g_bGeneral1ABSClose := TRUE;
  nSwitchState := 3;
END_IF;

CASE nSwitchState OF
  0:
  nSwitchState := 0;
  1:
  IF LREAL_TO_INT(g_fiFlatAbsType)=0 THEN
    g_fGeneral1ABSPos := g_General1_Axis.NCTOPLC.SETPOS + g_fiFlatAbsDistance;
  ELSIF LREAL_TO_INT(g_fiFlatAbsType)=1 THEN
    g_fGeneral1ABSPos := g_fiFlatAbsDistance;
  END_IF;
  nSwitchState := 2;
  2:
  g_bGeneral1ABSOpen := TRUE;

  IF g_bGeneral1ABSDone THEN
    g_boFlatAbsDone := TRUE;
    g_bGeneral1ABSOpen := FALSE;
    nSwitchState := 0;
  END_IF;
  3:
  Delay_Ton(IN := TRUE,PT := T#10ms);
  IF Delay_Ton.Q THEN
    g_bGeneral1ABSClose := FALSE;
    Delay_Ton(IN := FALSE);
    nSwitchState := 0;
  END_IF;
END_CASE;

IF bTonMaterialCylinder THEN
  g_boTonMaterialCylinder := TRUE;
ELSE
  g_boTonMaterialCylinder := FALSE;
END_IF;

IF g_bPlcResetBuffer THEN
  Delay_Ton(IN := FALSE);
  g_bGeneral1ABSOpen := FALSE;
  g_bGeneral1ABSClose := FALSE;
  nSwitchState := 0;
END_IF;
